  "159": { sourceSha256: "9f0f85c48154e21e22811ffa0b21533acd7a2504e7293b02be1310cea2649bda", preparedSha256: "50a351192787820a1be5fdf9faf9b064a7fdb7c5ad1589cc0c43cd9ce1d1ee56",
    general: "La Bravi Sprint es una plataforma eléctrica para reposición de existencias y preparación de pedidos en estanterías. Su ficha declara una altura de trabajo o elevación publicada de 5.350 mm y una plataforma de operador a 3,35 m. Las dimensiones son 1.560 × 808 × 1.441 mm. El texto de origen describe traslación eléctrica, giro sobre su propio eje y acceso a zonas estrechas de almacén. La especificación de batería aparece como cuatro unidades de 6 V y 180 Ah. El alcance real, los ciclos disponibles y la capacidad de carga deben confirmarse antes de planificar la operación." },
  "2063": { sourceSha256: "874af12e725dcc0631cc0c9eea16c1deea0b5d34470f59e435225b697390131b", preparedSha256: "1485525df99a17e66bd6644ad2ec3e1807803abe04c262b45992c01f92e2eda5",
    general: "La Hyster H14XD-12 es una carretilla elevadora diésel de gran tonelaje para cargas voluminosas en puertos e instalaciones industriales. Su ficha indica 14.500 kg de capacidad nominal a 1.200 mm de centro de carga y elevación de 7.000 mm. Las dimensiones son 7.806 × 2.541 × 4.008 mm; publica 19.328 kg de peso y un radio de giro de 4.953 mm. El proveedor describe un bastidor reforzado, equipos hidráulicos para ciclos de carga intensivos y distintas posibilidades de implementos. La capacidad admisible depende de la geometría de la mercancía y del accesorio instalado." },
  "2088": { sourceSha256: "39ea949c5dba851fb6a43f57c885e53ebf41459ed1514b791a6dbfb62160f442", preparedSha256: "f12f8b13c8a0f7bd529be3329584840bf58c64d3781ed1906a49ba15ca8cb84f",
    general: "La Hyster H4.5FTS5 es una carretilla elevadora diésel contrapesada para operaciones de manutención industrial. Declara 4.500 kg de capacidad nominal con centro de carga de 500 mm y altura de elevación de 5.300 mm. Sus dimensiones son 4.266 × 1.485 × 2.215 mm, con 7.520 kg de peso y radio de giro de 2.619 mm. La ficha identifica un motor de la familia Kubota de 3,8 litros y la descripción menciona distintas configuraciones de transmisión DuraMatch. La transmisión concreta, los accesorios y la capacidad residual deben confirmarse para la unidad seleccionada." },
  "2091": { sourceSha256: "3ad3f45aa4c57bc29f2d46017b78f482323706800a17dc08ab69e9122077ce8c", preparedSha256: "64ba19416c76f3e9b67dbf3ab2515e88e6771779ff929d609662461e4ce43ccc",
    general: "La Hyster H6.0FT es una carretilla elevadora diésel contrapesada destinada a manipular cargas pesadas en aplicaciones industriales y logísticas. La ficha declara 6.000 kg de capacidad nominal a 600 mm de centro de carga y 6.200 mm de altura de elevación. Sus dimensiones publicadas son 4.813 × 2.082 × 2.540 mm y registra 10.191 kg de peso. El radio de giro es de 3.320 mm. La descripción de origen menciona motorización Kubota y distintas opciones de transmisión para la familia Fortens. La capacidad en altura y la configuración específica de motor deben verificarse para cada equipo." },
  "2121": { sourceSha256: "7d8b7f5df6667a289f575fd2026e91933a7aad27592b7ba20b8a147edc908bc0", preparedSha256: "a88f5bfd53ae362147e87a8b09f14aa953a5c7834b56a82513e0591e772dac85",
    general: "La Hyster RS46-33XD/62 es una manipuladora telescópica de contenedores tipo reach stacker para operaciones portuarias y terminales logísticas. La ficha declara 46.000 kg de capacidad nominal, centro de carga de 1.865 mm y elevación de 15,26 m. El peso indicado es de 72.200 kg y el radio de giro de 8.420 mm. Se publica motorización diésel MTU de 10,7 litros y transmisión Dana S.O.H TE 30. La descripción de origen identifica una pluma hidráulica reforzada para manipulación de contenedores; la capacidad efectiva depende de su posición, alcance e implemento." },
