const digest = (value: string): string => createHash("sha256").update(value).digest("hex");

export const resolveGamVerifiedExtendedGeneral = (record: ProductRecord, preparedGeneral: string | null): string | null => {
  if (record.providerId !== "gam" || !record.reference || !preparedGeneral) return null;
  const expected = evidence[record.reference];
  if (!expected || !record.longDescription ||
    digest(preparedGeneral) !== expected.preparedSha256) return null;
  const source = JSON.stringify([
    record.providerId, record.reference, record.url, record.title, record.brand,
    record.model, record.categoryKey, record.condition, record.shortDescription,
    record.longDescription, record.specs
  ]);
  return digest(source) === expected.sourceSha256 ? expected.general : null;
};
